// Pin hinge leaf
// Print orientation: flat on bed, knuckles pointing up (+Z)

// ---- Plate ----
plate_len   = 60;    // plate length along X
plate_wid   = 25;    // plate width along Y
plate_thk   = 3;     // plate thickness along Z

// ---- Knuckles ----
knuckle_d   = 6;     // knuckle cylinder diameter
knuckle_n   = 5;     // number of knuckle segments
knuckle_pitch = plate_len / knuckle_n;  // 12 mm spacing
knuckle_y   = plate_wid / 2;            // 12.5 mm offset from centre
knuckle_z   = plate_thk;                // 3 mm, on top of plate

// ---- Pin hole ----
pin_d       = 2;     // pin hole diameter

// ---- Misc ----
eps         = 0.5;   // cutter overshoot past faces
$fn         = 96;    // curve resolution

difference() {
    // Base plate, centred in X/Y, resting on z = 0
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Knuckles on 1st, 3rd, 5th segments (odd indices)
    for (i = [0 : knuckle_n - 1]) {
        if (i % 2 == 0)
            translate([i * knuckle_pitch - knuckle_d/2,
                       knuckle_y,
                       knuckle_z])
                cylinder(d = knuckle_d, h = 6, $fn = 96); // 6 mm height

    }

    // Pin hole through every knuckle along the common X axis
    for (i = [0 : knuckle_n - 1]) {
        translate([i * knuckle_pitch - pin_d/2,
                   knuckle_y,
                   knuckle_z])
            translate([0, 0, -eps])
                cylinder(d = pin_d, h = 6 + 2 * eps, $fn = 64);
    }
}
