```openscad
// Pin hinge leaf
// Print orientation: flat on bed, knuckles pointing up (+Z)

$fn = 64;

// ---- Plate ----
plate_len   = 60;    // plate length along X
plate_wid   = 20;    // plate width along Y
plate_thk   = 3;     // plate thickness along Z

// ---- Knuckles ----
knuckle_d   = 7;     // knuckle cylinder diameter
knuckle_n   = 3;     // number of knuckles
knuckle_pitch = plate_len / knuckle_n; // 20 mm spacing
knuckle_y   = plate_wid / 2; // 10 mm, on +Y edge
knuckle_z   = plate_thk + 1.5; // 4.5 mm, axis height

// ---- Pin hole ----
pin_d       = 2.5;   // pin hole diameter

// ---- Cutting overlap ----
eps         = 0.5;   // extension past cut faces

difference() {
    union() {
        // Base plate
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckle cylinders (overlap into plate for a solid union)
        for (i = [0 : knuckle_n - 1]) {
            x = -plate_len/2 + i * knuckle_pitch;
            translate([x - knuckle_d/2, knuckle_y, knuckle_z])
                cylinder(d = knuckle_d, h = knuckle_d);
        }
    }

    // Pin hole through every knuckle along the common X axis
    for (i = [0 : knuckle_n - 1]) {
        x = -plate_len/2 + i * knuckle_pitch;
        translate([x - eps, knuckle_y, knuckle_z])
            cylinder(d = pin_d, h = knuckle_d + 2*eps);
    }
}
