    // 6-pointed star outline, first outer point on +X axis
    polygon(points = concat(
        [for (i = [0 : 5]) [outer_r, 0].rotate(i * 60)],
        [for (i = [0 : 5]) [inner_r, 0].rotate(i * 60 + 30)]
    ));

    // central through-hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2 * eps);
}

// ---------------- Build ----------------
translate([0, 0, 0])
    linear_extrude(height = plate_t)
        polygon(points = concat(
            [for (i = [0 : 5]) [outer_r, 0].rotate(i * 60)],
            [for (i = [0 : 5]) [inner_r, 0].rotate(i * 60 + 30)]
        ));
