            rotate(i * 360 / n_points + 180 / n_points) [inner_r, 0]],
        [[outer_r, 0]]
    ),
    fill = true);

    // Central through-hole
    translate([0, 0])
        cylinder(d = hole_d, h = plate_t + 2 * eps, $fn = 64);
}

