    polygon(points = concat(
        [for (i = [0 : n_points - 1])
            rotate(i * 360 / n_points) [outer_r, 0],
            rotate(i * 360 / n_points + 180 / n_points) [inner_r, 0]],
        [[outer_r, 0]]
