// Star-shaped indexing wheel
// Print orientation: flat on bed, z = 0 up to plate_t

// ---------------- Parameters ----------------
outer_r   = 35;    // distance of outer points from centre
inner_r   = 17.5;  // distance of inner points from centre
plate_t   = 4;     // plate thickness (Z)
hole_d    = 6;     // central through-hole diameter
eps       = 0.5;   // cutter overshoot past faces

n_points  = 5;     // number of star points
$fn       = 100;   // curve resolution

// ---------------- Model ----------------
difference() {
    // Solid star outline, extruded
    linear_extrude(height = plate_t)
        polygon(points = star_outline(outer_r, inner_r, n_points));

    // Central hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2 * eps);
}

// ---------------- Helpers ----------------
// Outline of a regular star: outer point on +X, then alternating
// outer/inner points evenly spaced in angle.
function star_outline(outer_r, inner_r, n_points) =
    concat(
        [[outer_r, 0]],
        [for (i = [0 : n_points - 1])
            rotate(i * 360 / n_points)
                [inner_r, 0]],
        [for (i = [0 : n_points - 1])
            rotate((i + 0.5) * 360 / n_points)
                [outer_r, 0]]
    );
