    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2 * eps);
}

// ---------------- Single point (reference) ----------------
// x = R cos(theta), y = R sin(theta)
function pt(R, theta) = [R * cos(theta), R * sin(theta)];
