// Tapered riser block for setting a beaker higher
// Print orientation: wide base on the bed (z = 0), narrow top at z = 30

// ---------- Dimensions (mm) ----------
base_size   = 80;   // bottom square side length
top_size    = 50;   // top square side length
height      = 30;   // overall height of the frustum
pocket_w    = 40;   // square pocket side length (top face)
pocket_d    = 5;    // square pocket depth
eps         = 0.5;  // overshoot for clean boolean cuts

$fn = 64;

// ---------- Model ----------
difference() {
    // Square frustum body
    linear_extrude(height = height)
        hull() {
            translate([-base_size / 2, -base_size / 2]) square(base_size);
            translate([-top_size / 2, -top_size / 2])    square(top_size);
        }

    // Square pocket cut into the top face
    translate([0, 0, height - pocket_d])
        cube([pocket_w, pocket_w, pocket_d + eps]);
}
