// Spoked wheel for small sample cart
// Print orientation: flat on bed, z = 0 upward

// ---- Dimensions (mm) ----
wheel_od      = 80;    // outer rim diameter
wheel_w       = 5;     // rim width (also part thickness)
hub_d         = 16;    // hub diameter
axle_d        = 5;     // axle hole diameter
spoke_count   = 8;     // number of spokes
spoke_w       = 5;     // spoke width
eps           = 0.5;   // cutter overshoot

$fn = 128;

// ---- Model ----
difference() {
    union() {
        // Outer rim
        cylinder(d = wheel_od, h = wheel_w);
        // Hub
        translate([0, 0, -eps])
            cylinder(d = hub_d, h = wheel_w + 2 * eps);
        // Spokes
        for (i = [0 : spoke_count - 1])
            rotate([0, 0, i * 360 / spoke_count])
                translate([hub_d / 2 - 1, -spoke_w / 2, 0])
                    cube([(wheel_od - hub_d) / 2 + 2, spoke_w, wheel_w]);
    }
    // Axle hole
    translate([0, 0, -eps])
        cylinder(d = axle_d, h = wheel_w + 2 * eps);
}
