knuckle_y   = plate_wid / 2; // 15 mm (on +Y edge)
knuckle_z   = 4;     // axis height above bed

// --- Pin hole ---
pin_d       = 2.5;   // pin hole diameter

// --- Cutting overlap ---
eps         = 0.5;   // extension past cut faces

difference() {
    union() {
        // Base plate
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckle cylinders (1st, 3rd, 5th segments)
        for (i = [0 : 2 : 4]) {
            x0 = -plate_len/2 + (i + 1) * knuckle_pitch;
            translate([x0, knuckle_y, 0])
                cylinder(d = knuckle_d, h = plate_thk + eps);
        }
    }

    // Pin hole along the knuckle axis
    translate([-plate_len/2 - eps, knuckle_y, knuckle_z])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = plate_len + 2*eps);
}
