// Star-shaped indexing wheel
// Print orientation: flat on bed, z = 0 up to plate_t

// ---------------- Parameters ----------------
outer_r   = 40;    // distance of outer points from centre
inner_r   = 20;    // distance of inner points from centre
point_n   = 6;     // number of points (star has this many outer and inner points)
plate_t   = 5;     // plate thickness (Z)
hole_d    = 8;     // central through-hole diameter
eps       = 0.5;   // cutter overshoot past faces

$fn = 128;         // smoothness of curved shapes

// ---------------- Model ----------------
difference() {
    // Star outline, centred on origin, first outer point on +X axis
    polygon(points = star_points(outer_r, inner_r, point_n));

    // Through-hole at centre
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2 * eps);
}

// ---------------- Helpers ----------------
// Alternate between outer and inner radii for the 2n vertices
function star_points(outer, inner, n) {
    res = [];
    for (i = [0 : n - 1]) {
        angle = i * 360 / n;
        push(res, [outer * cos(angle), outer * sin(angle)]);
        push(res, [inner * cos(angle + 180 / n),
                   inner * sin(angle + 180 / n)]);
    }
    return res;
}

function push(arr, v) {
    arr = arr || [];
    arr = arr + [v];
    return arr;
}
