// Spoked wheel for a small sample cart
// Print orientation: flat on the bed, centred on the origin

// ---------------- Parameters ----------------
wheel_od      = 80;    // outer diameter of the rim (mm)
rim_width     = 4;     // width of the rim (mm)
hub_d         = 16;    // hub diameter (mm)
axle_hole     = 5;     // axle hole diameter (mm)
spoke_count   = 4;     // number of spokes
spoke_w       = 4;     // spoke width (mm)
spoke_start   = 0;     // angle of the first spoke (deg, 0 = +X axis)
thickness     = 5;     // wheel thickness (mm)
eps           = 0.5;   // cutter overshoot past faces (mm)

$fn = 128;             // smoothness of curved shapes

// ---------------- Derived ----------------
rim_id = wheel_od - 2 * rim_width;   // inner diameter of the rim (hub + spokes)
spoke_len = (wheel_od / 2) - (hub_d / 2); // radial length of each spoke

// ---------------- Model ----------------
difference() {
    // Outer rim (ring)
    cylinder(d = wheel_od, h = thickness);

    // Hub (overlaps the spokes for a solid centre)
    translate([0, 0, -eps])
        cylinder(d = hub_d, h = thickness + 2 * eps);

    // Axle hole through the hub
    translate([0, 0, -eps])
        cylinder(d = axle_hole, h = thickness + 2 * eps);

    // Spokes, evenly spaced around the circle
    for (i = [0 : spoke_count - 1])
        rotate([0, 0, spoke_start + i * 360 / spoke_count])
            translate([hub_d / 2 - 0.01, -spoke_w / 2, 0])
                cube([spoke_len + 0.01, spoke_w, thickness]);
}
