            cube([plate_len, plate_wid, plate_thk]);

        // Knuckle cylinders (overlap slightly into plate for a solid union)
        for (i = [0 : knuckle_n - 1]) {
            x = -plate_len/2 + i * knuckle_pitch;
            translate([x - knuckle_d/2, knuckle_y, knuckle_z])
                cylinder(d = knuckle_d, h = plate_thk + knuckle_d + 2*eps);
