    linear_extrude(height = block_h)
        hull() {
            translate([-base_size / 2, -base_size / 2]) square(base_size);
            translate([-top_size / 2, -top_size / 2]) square(top_size);
        }

    // Pocket cut into the top face
    translate([0, 0, block_h - pocket_depth])
        cube([pocket_w, pocket_w, pocket_depth + eps]);
}
