// Spoked wheel for a small sample cart
// Print orientation: flat on the bed, centred on the origin

// ---------------- Parameters ----------------
wheel_od      = 60;    // outer diameter of the rim (mm)
wheel_width   = 5;     // rim width / part thickness (mm)
hub_d         = 14;    // hub diameter (mm)
axle_d        = 8;     // axle hole diameter (mm)
spoke_count   = 8;     // number of spokes
spoke_w       = 4;     // spoke width (mm)
spoke_start   = 0;     // angle of the first spoke (deg, 0 = +X axis)
eps           = 0.5;   // cutter overshoot past faces (mm)
$fn           = 128;   // circle resolution

// Derived
rim_id = wheel_od - 2 * wheel_width;   // inner diameter of the rim (50 mm)
spoke_len = (wheel_od / 2) - (hub_d / 2); // radial length of each spoke

// ---------------- Model ----------------
difference() {
    union() {
        // Outer rim (ring)
        cylinder(d = wheel_od, h = wheel_width);

        // Hub
        translate([0, 0, 0])
            cylinder(d = hub_d, h = wheel_width);

        // Spokes, evenly spaced
        for (i = [0 : spoke_count - 1]) {
            rotate([0, 0, spoke_start + i * 360 / spoke_count])
                translate([0, -spoke_w / 2, 0])
                    cube([spoke_len, spoke_w, wheel_width]);
        }
    }

    // Axle hole through the hub centre
    translate([0, 0, -eps])
        cylinder(d = axle_d, h = wheel_width + 2 * eps);
}
```

```openscad
// Spoked wheel for small sample cart
// Print orientation: flat on bed, z = 0 up to part thickness

// ---------- Parameters ----------
part_thickness   = 5;     // wheel thickness (Z)
outer_diameter   = 60;    // outer rim diameter
rim_width        = 5;     // rim width (radial)
hub_diameter     = 14;    // hub diameter
axle_hole_d      = 8;     // axle hole diameter
spoke_count      = 8;     // number of spokes
spoke_width      = 4;     // spoke width (tangential)
spoke_start_ang  = 0;     // first spoke along +X axis (degrees)
cut_extra        = 0.5;   // overshoot for clean boolean cuts
$fn              = 128;   // curve resolution

// ---------- Derived ----------
outer_r = outer_diameter / 2;
inner_r = outer_r - rim_width;   // rim inner radius
hub_r   = hub_diameter / 2;

// ---------- Model ----------
difference() {
    union() {
        // Outer rim
        difference() {
            cylinder(h = part_thickness, r = outer_r);
            translate([0, 0, -cut_extra])
                cylinder(h = part_thickness + 2 * cut_extra, r = inner_r);
        }

        // Hub
        cylinder(h = part_thickness, r = hub_r);
    }

    // Axle hole through hub centre
    translate([0, 0, -cut_extra])
        cylinder(h = part_thickness + 2 * cut_extra, d = axle_hole_d);

    // Spokes
    for (i = [0 : spoke_count - 1]) {
        rotate([0, 0, spoke_start_ang + i * 360 / spoke_count])
            translate([hub_r, -spoke_width / 2, 0])
