        [rotate((point_n / 2 - 0.5) * 360 / point_n) [inner_r, 0]]
    ),
    // Centre through-hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2 * eps);
}

// ---------------- Misc ----------------
difference() {
    linear_extrude(height = plate_t)
        polygon(points = concat(
            [for (i = [0 : point_n / 2 - 1])
                rotate(i * 360 / point_n) [outer_r, 0],
                rotate((i + 0.5) * 360 / point_n) [inner_r, 0]],
            [rotate((point_n / 2 - 0.5) * 360 / point_n) [inner_r, 0]]
        ));
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2 * eps);
}
