    union() {
        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on 1st, 3rd, 5th segments (i = 0, 2, 4)
        for (i = [0 : 2 : knuckle_n - 1])
            translate([seg_x(i), plate_wid/2 - 1, plate_thk - 0.01])
                cylinder(d = knuckle_d, h = knuckle_h + 0.01);
    }

    // Pin hole along the common axis (y = 15, z = 3) through every knuckle
    for (i = [0 : 2 : knuckle_n - 1])
        translate([seg_x(i) + 0.5, plate_wid/2 - 1, 3])
            rotate([0, 90, 0])
                cylinder(d = pin_d, h = knuckle_d + 2*eps, center = true);
