knuckle_y   = 12.5;  // knuckle axis Y position (mm)
knuckle_z   = 4;     // knuckle axis Z height (mm)
pin_d       = 2;     // pin hole diameter (mm)

eps         = 0.5;   // cutter overshoot past faces (mm)
$fn         = 96;    // curve resolution

// Derived
seg_len = plate_len / knuckle_n;   // 8 mm segment length

// ---------------- Model ----------------
difference() {
    union() {
        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on 1st, 3rd, 5th segments (odd indices)
        for (i = [0 : 2 : knuckle_n - 1]) {
            x_c = -plate_len/2 + (i + 1) * seg_len;
            translate([x_c - knuckle_d/2, knuckle_y, knuckle_z])
                cylinder(d = knuckle_d, h = plate_thk + 4);
        }
