```openscad
// Star-shaped indexing wheel
// Print orientation: flat on bed, z = 0 up to plate_t

// ---------------- Parameters ----------------
outer_r   = 30;    // distance of outer points from centre (mm)
inner_r   = 18;    // distance of inner points from centre (mm)
plate_t   = 3;     // plate thickness (mm)
hole_d    = 6;     // central through-hole diameter (mm)
n_points  = 5;     // number of points (star is n outer + n inner)
eps       = 0.5;   // cutter overshoot past faces (mm)
$fn       = 128;   // curve resolution

// ---------------- Model ----------------
difference() {
    // Solid star plate
    linear_extrude(height = plate_t)
        polygon(points = star_points(outer_r, inner_r, n_points));

    // Central through-hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2 * eps);
}

// ---------------- Helpers ----------------
// Outline of a regular star: outer points on +X, then alternating
// inner/outer points evenly spaced in angle.
function star_points(outer_r, inner_r, n) {
    pts = [];
    for (i = [0 : n - 1]) {
        a = i * 360 / n;
        pts += [outer_r * [cos(a), sin(a)]];   // outer point
        if (i < n - 1)
            pts += [inner_r * [cos(a + 180 / n), sin(a + 180 / n)]]; // inner point
    }
    return pts;
}
