```openscad
// Spoked wheel for small sample cart
// Flat part, printed lying flat on the bed, centred on origin

// ---- Dimensions (mm) ----
part_thickness      = 6;    // wheel thickness (Z)
outer_diameter      = 100;  // outer rim diameter
rim_width           = 6;    // rim width (radial)
hub_diameter        = 20;   // hub diameter
axle_hole_diameter  = 8;    // central axle hole diameter
spoke_count         = 6;    // number of spokes
spoke_width         = 4;    // spoke width (tangential)
first_spoke_angle   = 0;    // first spoke along +X axis (degrees)

// ---- Derived ----
outer_radius        = outer_diameter / 2;
rim_inner_radius    = outer_radius - rim_width;
hub_radius          = hub_diameter / 2;
axle_hole_radius    = axle_hole_diameter / 2;
spoke_length        = outer_radius - hub_radius; // hub to rim

// ---- Modelling ----
$fn = 128;

module wheel() {
    difference() {
        union() {
            // Outer rim (ring)
            cylinder(h = part_thickness, r = outer_radius);

            // Spokes, radially from hub to rim, evenly spaced
            for (i = [0 : spoke_count - 1]) {
                rotate([0, 0, first_spoke_angle + i * 360 / spoke_count])
                    translate([hub_radius, -spoke_width / 2, 0])
                        cube([spoke_length, spoke_width, part_thickness]);
            }
        }

            // Hub (overlaps rim for a solid union, cleaned by the axle hole)
            translate([0, 0, -1])
                cylinder(h = part_thickness + 2, r = hub_radius);

            // Central axle hole through the hub
            translate([0, 0, -1])
                cylinder(h = part_thickness + 2, r = axle_hole_radius);
    }
}

wheel();
