// Spoked wheel for small sample cart
// Print orientation: flat on bed, centred on origin

// ---- Dimensions (mm) ----
outer_d      = 100;   // outer rim diameter
rim_w        = 6;     // rim width
hub_d        = 20;    // hub diameter
axle_hole_d  = 6;     // axle hole diameter
spoke_count  = 4;     // number of spokes
spoke_w      = 5;     // spoke width
spoke_start  = 0;     // angle of first spoke (deg, +X axis)
eps          = 0.5;   // cutter overshoot

$fn = 128;

outer_r = outer_d / 2;
hub_r   = hub_d / 2;

difference() {
    // Outer disc
    cylinder(h = rim_w, r = outer_r);

    // Rim (leaves hub area clear)
    translate([0, 0, -eps])
        cylinder(h = rim_w + 2 * eps, r = outer_r - rim_w / 2);

    // Hub
    translate([0, 0, -eps])
        cylinder(h = rim_w + 2 * eps, r = hub_r);

    // Axle hole
    translate([0, 0, -1])
        cylinder(h = rim_w + 2, d = axle_hole_d);

    // Spokes
    for (i = [0 : spoke_count - 1])
        rotate([0, 0, spoke_start + i * 360 / spoke_count])
            translate([hub_r - 1, -spoke_w / 2, -eps])
                cube([outer_r - hub_r + 2, spoke_w, rim_w + 2 * eps]);
}
