        // Outer rim (ring)
        cylinder(h = part_thickness, r = outer_r);

        // Hub
        translate([0, 0, 0])
            cylinder(h = part_thickness, r = hub_r);

        // Spokes: from hub outer edge to rim inner edge
        for (i = [0 : spoke_count - 1]) {
            rotate([0, 0, spoke_start_ang + i * 360 / spoke_count])
                translate([hub_r, -spoke_width / 2, 0])
                    cube([inner_r - hub_r, spoke_width, part_thickness]);
        }
    }

    // Axle hole through hub centre
    translate([0, 0, -eps])
        cylinder(h = part_thickness + 2 * eps, d = axle_hole_d);
