// X position of segment i (0..knuckle_n-1), each 8 mm wide
function seg_center(i) = (i - (knuckle_n - 1) / 2) * plate_len / knuckle_n;

difference() {
    union() {
        // Base plate, centred on origin in X/Y
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckle cylinders on 1st, 3rd, 5th segments
        for (i = [0 : 2 : knuckle_n - 1])
            translate([seg_center(i), 10, knuckle_z])
                cylinder(d = knuckle_d, h = 10);
    }

    // Pin hole through every knuckle along the common X axis at y=10
    for (i = [0 : 2 : knuckle_n - 1])
        translate([seg_center(i) - eps, 10, knuckle_z])
            cylinder(d = pin_d, h = 10 + 2*eps);
}
