        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_len / 2, -plate_wid / 2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on 1st, 3rd, 5th segments (odd indices)
        for (i = [1 : 2 : knuckle_n - 1]) {
            x_c = -plate_len / 2 + i * pitch;
            translate([x_c - knuckle_r, plate_wid / 2, knuckle_z])
                cylinder(r = knuckle_r, h = 10);
        }
    }

    // Pin hole through every knuckle along the common X axis
    translate([-plate_len / 2 - eps, plate_wid / 2, knuckle_z])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = plate_len + 2 * eps);
