// Spoked wheel for a small sample cart
// Print orientation: flat on the bed, centred on the origin

// ---------------- Parameters ----------------
wheel_od      = 60;   // outer diameter of the rim (mm)
wheel_width   = 6;    // rim width (mm)
hub_d         = 16;   // hub diameter (mm)
axle_d        = 6;    // axle hole diameter (mm)
spoke_count   = 5;    // number of spokes
spoke_w       = 4;    // spoke width (mm)
spoke_start   = 0;    // angle of the first spoke (deg, 0 = +X axis)
eps           = 0.5;  // cutter overshoot past faces (mm)
$fn           = 96;   // circle resolution

// Derived
rim_id = wheel_od - 2 * wheel_width;  // inner diameter of the rim

// ---------------- Model ----------------
difference() {
    union() {
        // Outer rim (ring)
        cylinder(d = wheel_od, h = wheel_width);

        // Hub
        translate([0, 0, -0.01])
            cylinder(d = hub_d, h = wheel_width + 0.02);

        // Spokes: radial blocks from hub to rim, evenly spaced
        for (i = [0 : spoke_count - 1]) {
            rotate([0, 0, spoke_start + i * 360 / spoke_count])
                translate([hub_d / 2 - 1, -spoke_w / 2, 0])
                    cube([wheel_od / 2 - hub_d / 2 + 2,
                          spoke_w,
                          wheel_width]);
        }
    }

    // Axle hole through the hub centre
    translate([0, 0, -eps])
        cylinder(d = axle_d, h = wheel_width + 2 * eps);
}
